import React, { useState } from 'react';

export let imageUrlParser = (url: string) => url;

const fallback =
  'data:image/png;base64,';

export interface ImagePreviewConfig {
  visible?: boolean;
  src?: string;
  onVisibleChange?: (visible: boolean) => void;
}

export interface ImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  fallback?: string;
  preview?: boolean | ImagePreviewConfig;
  wrapperClassName?: string;
}

export const Image: React.FC<ImageProps> = React.memo((props) => {
  const {
    preview = false,
    fallback,
    wrapperClassName,
    onError,
    onClick,
    src: source,
    ...rest
  } = props;
  const [visible, setVisible] = useState(false);
  const previewConfig = typeof preview === 'object' ? preview : undefined;
  const isVisible = previewConfig?.visible ?? visible;
  const src = source ? imageUrlParser(String(source)) : undefined;
  const previewSrc = previewConfig?.src ?? src;
  const setPreviewVisible = (value: boolean) => {
    setVisible(value);
    previewConfig?.onVisibleChange?.(value);
  };

  return (
    <span className={wrapperClassName} style={{ display: 'inline-block' }}>
      <img
        {...rest}
        src={src}
        loading={rest.loading ?? 'lazy'}
        onError={(event) => {
          onError?.(event);
          if (fallback && event.currentTarget.src !== fallback) {
            event.currentTarget.src = fallback;
          }
        }}
        onClick={(event) => {
          onClick?.(event);
          if (preview === true) {
            setPreviewVisible(true);
          }
        }}
      />
      {preview !== false && isVisible && previewSrc && (
        <div
          role="dialog"
          aria-label="Image preview"
          onClick={() => setPreviewVisible(false)}
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 1000,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 24,
            background: 'rgb(0 0 0 / 75%)',
          }}
        >
          <button
            type="button"
            aria-label="Close image preview"
            onClick={() => setPreviewVisible(false)}
            style={{
              position: 'absolute',
              top: 16,
              right: 20,
              color: '#fff',
              fontSize: 28,
              lineHeight: 1,
              background: 'transparent',
              border: 0,
              cursor: 'pointer',
            }}
          >
            ×
          </button>
          <img
            src={previewSrc}
            alt={rest.alt}
            onClick={(event) => event.stopPropagation()}
            style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }}
          />
        </div>
      )}
    </span>
  );
});
Image.displayName = 'Image';

export function setImageUrlParser(parser: (url: string) => string): void {
  imageUrlParser = parser;
}
